{
  "findings": [
    {
      "check_id": "CKV_GCP_32",
      "title": "Project-wide SSH keys are not blocked",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "The instance metadata does not block project-wide SSH keys, allowing centrally configured SSH keys to grant access to this disaster-recovery orchestration VM."
    },
    {
      "check_id": "CKV_GCP_38",
      "title": "Boot disk lacks customer-supplied encryption",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "The boot disk for this disaster-recovery orchestration instance relies only on Google-managed encryption and does not specify a customer-supplied encryption key."
    },
    {
      "check_id": "CKV_GCP_30",
      "title": "Default Compute Engine service account is used",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "The instance explicitly uses the project's default Compute Engine service account, which commonly has broader permissions and is shared with other workloads."
    },
    {
      "check_id": "CKV_GCP_31",
      "title": "Default service account has full Cloud API scope",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "The default Compute Engine service account is combined with the cloud-platform OAuth scope, increasing the impact if the instance or its credentials are compromised."
    },
    {
      "check_id": "CKV_GCP_40",
      "title": "Compute instance has a public IP address",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "The empty access_config block assigns an ephemeral public IP to an orchestration instance that is tagged and networked as an internal disaster-recovery component."
    },
    {
      "check_id": "CKV_GCP_35",
      "title": "Serial port access is enabled",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "The serial-port-enable metadata value is explicitly true, exposing an additional administrative access path that could bypass normal network controls."
    },
    {
      "check_id": "CKV_GCP_39",
      "title": "Shielded VM protections are not enabled",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "The instance does not configure Secure Boot, vTPM, or integrity monitoring, reducing protection against boot-level tampering on this orchestration workload."
    }
  ],
  "patched_code": "variable \"backup_orchestration_disk_encryption_key\" {\n  description = \"Base64-encoded 256-bit customer-supplied encryption key for the backup orchestration boot disk.\"\n  type        = string\n  sensitive   = true\n}\n\nresource \"google_service_account\" \"backup_orchestration_engine\" {\n  account_id   = \"backup-orchestration-engine\"\n  display_name = \"Backup Orchestration Engine\"\n}\n\nresource \"google_compute_instance\" \"backup_orchestration_engine\" {\n  name         = \"enterprise-disaster-recovery-orchestration-platform-compute-orchestration\"\n  machine_type = \"e2-medium\"\n  zone         = \"${var.primary_region}-a\"\n  boot_disk {\n    initialize_params {\n      image = \"debian-cloud/debian-11\"\n      size  = 50\n    }\n    disk_encryption_key {\n      raw_key = var.backup_orchestration_disk_encryption_key\n    }\n  }\n  network_interface {\n    network    = google_compute_network.dr_vpc.id\n    subnetwork = google_compute_subnetwork.management_subnet.id\n  }\n  service_account {\n    email  = google_service_account.backup_orchestration_engine.email\n    scopes = [\"cloud-platform\"]\n  }\n  metadata = {\n    block-project-ssh-keys = true\n    serial-port-enable     = false\n    startup-script         = file(\"${path.module}/scripts/orchestration-startup.sh\")\n  }\n  shielded_instance_config {\n    enable_secure_boot          = true\n    enable_vtpm                 = true\n    enable_integrity_monitoring = true\n  }\n  tags = [\"dr-internal\", \"orchestration-engine\"]\n  depends_on = [\n    google_storage_bucket.primary_backup_storage,\n    google_sql_database_instance.recovery_database\n  ]\n}\n",
  "fix_summary": "Removed the public IP, blocked project-wide SSH keys, disabled serial-port access, and enabled all Shielded VM protections. The instance now uses a dedicated service account and a sensitive, caller-supplied disk encryption key instead of the default service account and Google-managed disk encryption alone."
}
